CREATE OR REPLACE FUNCTION public.create_lesson_with_next_order(target_course_id uuid, target_folder_id uuid, lesson_title text, lesson_slug text, lesson_description text, lesson_duration integer, lesson_is_free boolean, lesson_is_required boolean, lesson_publication_status text)
 RETURNS lessons
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  next_lesson_order INTEGER;
  created_lesson public.lessons%ROWTYPE;
  base_slug TEXT;
  candidate_slug TEXT;
  slug_suffix INTEGER := 1;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Silakan masuk terlebih dahulu.'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.courses
  WHERE id = target_course_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Course tidak ditemukan.'
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT private.can_manage_course(target_course_id) THEN
    RAISE EXCEPTION 'Anda tidak memiliki izin mengelola Course ini.'
      USING ERRCODE = '42501';
  END IF;

  IF target_folder_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.lesson_folders
    WHERE id = target_folder_id
      AND course_id = target_course_id
  ) THEN
    RAISE EXCEPTION 'Folder tidak ditemukan pada Course ini.'
      USING ERRCODE = '22023';
  END IF;

  IF BTRIM(COALESCE(lesson_title, '')) = '' THEN
    RAISE EXCEPTION 'Judul Lesson wajib diisi.'
      USING ERRCODE = '22023';
  END IF;

  IF BTRIM(COALESCE(lesson_slug, '')) = '' THEN
    RAISE EXCEPTION 'Slug wajib diisi.'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(lesson_duration, 0) <= 0 THEN
    RAISE EXCEPTION 'Durasi Lesson harus lebih dari 0 menit.'
      USING ERRCODE = '22023';
  END IF;

  IF lesson_publication_status NOT IN ('draft', 'published') THEN
    RAISE EXCEPTION 'Status publikasi Lesson tidak valid.'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(MAX(lesson_order), 0) + 1
  INTO next_lesson_order
  FROM public.lessons
  WHERE course_id = target_course_id;

  base_slug := BTRIM(lesson_slug);
  candidate_slug := base_slug;

  LOOP
    BEGIN
      INSERT INTO public.lessons (
        course_id,
        folder_id,
        title,
        slug,
        description,
        lesson_order,
        duration,
        is_free,
        is_required,
        publication_status
      )
      VALUES (
        target_course_id,
        target_folder_id,
        BTRIM(lesson_title),
        candidate_slug,
        NULLIF(BTRIM(COALESCE(lesson_description, '')), ''),
        next_lesson_order,
        lesson_duration,
        COALESCE(lesson_is_free, FALSE),
        COALESCE(lesson_is_required, TRUE),
        lesson_publication_status
      )
      RETURNING * INTO created_lesson;

      RETURN created_lesson;
    EXCEPTION
      WHEN unique_violation THEN
        IF NOT EXISTS (
          SELECT 1
          FROM public.lessons
          WHERE slug = candidate_slug
        ) THEN
          RAISE;
        END IF;

        slug_suffix := slug_suffix + 1;
        IF slug_suffix > 1000 THEN
          RAISE EXCEPTION 'Slug unik tidak dapat dibuat secara otomatis.';
        END IF;

        candidate_slug := base_slug || '-' || slug_suffix::TEXT;
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_student_password(target_profile_id uuid, new_password text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  target_role text;
begin
  if not private.is_active_admin() then
    raise exception 'Anda tidak memiliki izin sebagai admin.'
      using errcode = '42501';
  end if;

  if target_profile_id is null then
    raise exception 'Akun mahasiswa tidak ditemukan.'
      using errcode = '22023';
  end if;

  if new_password is null or length(btrim(new_password)) < 6 then
    raise exception 'Password baru minimal 6 karakter.'
      using errcode = '22023';
  end if;

  if octet_length(new_password) > 72 then
    raise exception 'Password baru maksimal 72 byte.'
      using errcode = '22023';
  end if;

  select p.role::text
  into target_role
  from public.profiles p
  join auth.users u on u.id = p.id
  where p.id = target_profile_id
  for update of p, u;

  if not found then
    raise exception 'Akun mahasiswa tidak ditemukan.'
      using errcode = 'P0002';
  end if;

  if target_role <> 'student' then
    raise exception 'Password dari menu ini hanya dapat diubah untuk akun mahasiswa.'
      using errcode = '42501';
  end if;

  update auth.users
  set encrypted_password = extensions.crypt(
        new_password,
        extensions.gen_salt('bf', 10)
      ),
      updated_at = now()
  where id = target_profile_id;

  if not found then
    raise exception 'Password mahasiswa gagal diubah.';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_promote_student_to_mentor(target_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'private', 'pg_temp'
AS $function$
declare
  target_role text;
  mentor_detail_id uuid;
begin
  if not private.is_active_admin() then
    raise exception 'Anda tidak memiliki izin sebagai admin.'
      using errcode = '42501';
  end if;

  if target_profile_id is null then
    raise exception 'Akun mahasiswa tidak ditemukan.'
      using errcode = '22023';
  end if;

  select p.role::text
  into target_role
  from public.profiles p
  where p.id = target_profile_id
  for update;

  if not found then
    raise exception 'Akun mahasiswa tidak ditemukan.'
      using errcode = 'P0002';
  end if;

  if target_role <> 'student' then
    raise exception 'Hanya akun mahasiswa yang dapat dijadikan mentor dari menu ini.'
      using errcode = '42501';
  end if;

  update public.profiles
  set role = 'mentor'::public.profile_role,
      updated_at = now()
  where id = target_profile_id;

  insert into public.mentor_details (profile_id)
  values (target_profile_id)
  on conflict (profile_id)
  do update set updated_at = now()
  returning id into mentor_detail_id;

  return mentor_detail_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.enforce_tryout_question_option_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_question_id uuid;
  option_count integer;
  correct_count integer;
  minimum_order integer;
  maximum_order integer;
begin
  if tg_table_name = 'tryout_questions' then
    if tg_op = 'DELETE' then
      target_question_id := old.id;
    else
      target_question_id := new.id;
    end if;
  elsif tg_op = 'DELETE' then
    target_question_id := old.question_id;
  else
    target_question_id := new.question_id;
  end if;

  if not exists (
    select 1
    from public.tryout_questions q
    where q.id = target_question_id
  ) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  select
    count(*)::integer,
    count(*) filter (where o.is_correct)::integer,
    min(o.option_order),
    max(o.option_order)
  into option_count, correct_count, minimum_order, maximum_order
  from public.tryout_options o
  where o.question_id = target_question_id;

  if option_count not in (4, 5)
     or correct_count <> 1
     or minimum_order <> 1
     or maximum_order <> option_count then
    raise exception 'Setiap soal Try Out wajib memiliki pilihan A-D atau A-E dan tepat satu jawaban benar.'
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_tryout_question(target_tryout_id uuid, question_text text, explanation_text text, question_image_path text, explanation_image_path text, topic_text text, difficulty_text text, question_points integer, option_texts text[], correct_option_index integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  new_question_id uuid;
  next_order integer;
  option_count integer;
  option_index integer;
begin
  if not public.can_manage_tryout(target_tryout_id) then
    raise exception 'Anda tidak dapat mengelola Try Out ini.';
  end if;

  if char_length(btrim(question_text)) = 0 then
    raise exception 'Pertanyaan wajib diisi.';
  end if;

  option_count := array_length(option_texts, 1);
  if option_count not in (4, 5)
     or exists (
       select 1
       from unnest(option_texts) as option_value(value)
       where char_length(btrim(value)) = 0
     ) then
    raise exception 'Pilihan jawaban wajib terdiri dari A-D atau A-E.';
  end if;

  if correct_option_index < 1 or correct_option_index > option_count then
    raise exception 'Jawaban benar harus sesuai dengan jumlah pilihan.';
  end if;

  select coalesce(max(q.question_order), 0) + 1
  into next_order
  from public.tryout_questions q
  where q.tryout_id = target_tryout_id;

  insert into public.tryout_questions (
    tryout_id,
    question_order,
    question,
    explanation,
    image_path,
    explanation_image_path,
    topic,
    difficulty,
    points
  ) values (
    target_tryout_id,
    next_order,
    btrim(question_text),
    nullif(btrim(explanation_text), ''),
    nullif(btrim(question_image_path), ''),
    nullif(btrim(explanation_image_path), ''),
    coalesce(nullif(btrim(topic_text), ''), 'Umum'),
    difficulty_text,
    question_points
  ) returning id into new_question_id;

  for option_index in 1..option_count loop
    insert into public.tryout_options (
      question_id,
      option_order,
      option_text,
      is_correct
    ) values (
      new_question_id,
      option_index,
      btrim(option_texts[option_index]),
      option_index = correct_option_index
    );
  end loop;

  return new_question_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_tryout_question(target_question_id uuid, question_text text, explanation_text text, question_image_path text, explanation_image_path text, topic_text text, difficulty_text text, question_points integer, option_texts text[], correct_option_index integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_tryout_id uuid;
  option_count integer;
  option_index integer;
begin
  select q.tryout_id
  into target_tryout_id
  from public.tryout_questions q
  where q.id = target_question_id;

  if target_tryout_id is null
     or not public.can_manage_tryout(target_tryout_id) then
    raise exception 'Soal Try Out tidak ditemukan atau tidak dapat Anda kelola.';
  end if;

  if char_length(btrim(question_text)) = 0 then
    raise exception 'Pertanyaan wajib diisi.';
  end if;

  option_count := array_length(option_texts, 1);
  if option_count not in (4, 5)
     or exists (
       select 1
       from unnest(option_texts) as option_value(value)
       where char_length(btrim(value)) = 0
     ) then
    raise exception 'Pilihan jawaban wajib terdiri dari A-D atau A-E.';
  end if;

  if correct_option_index < 1 or correct_option_index > option_count then
    raise exception 'Jawaban benar harus sesuai dengan jumlah pilihan.';
  end if;

  update public.tryout_questions
  set
    question = btrim(question_text),
    explanation = nullif(btrim(explanation_text), ''),
    image_path = nullif(btrim(question_image_path), ''),
    explanation_image_path = nullif(btrim(explanation_image_path), ''),
    topic = coalesce(nullif(btrim(topic_text), ''), 'Umum'),
    difficulty = difficulty_text,
    points = question_points
  where id = target_question_id;

  delete from public.tryout_options
  where question_id = target_question_id;

  for option_index in 1..option_count loop
    insert into public.tryout_options (
      question_id,
      option_order,
      option_text,
      is_correct
    ) values (
      target_question_id,
      option_index,
      btrim(option_texts[option_index]),
      option_index = correct_option_index
    );
  end loop;

  return target_question_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.leader_can_access_profile(target_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    private.is_active_leader()
    and (
      (
        private.leader_has_permission('manage_enrollment')
        and exists (
          select 1
          from public.enrollments e
          where e.profile_id = target_profile_id
            and private.leader_can_access_course(e.course_id)
        )
      )
      or
      (
        private.leader_has_permission('manage_messages')
        and exists (
          select 1
          from public.lesson_message_threads t
          where t.student_profile_id = target_profile_id
            and private.leader_can_access_course(t.course_id)
        )
      )
    );
$function$

CREATE OR REPLACE FUNCTION private.set_master_audit_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.created_by is null then
      new.created_by := (select auth.uid());
    end if;
    new.updated_by := coalesce((select auth.uid()), new.updated_by);
  else
    new.updated_by := coalesce((select auth.uid()), new.updated_by);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_leader_parent_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_active_leader() then
    return new;
  end if;

  if tg_table_name = 'programs'
     and new.organization_id is distinct from old.organization_id
     and not private.leader_can_access_organization(new.organization_id) then
    raise exception 'Program tidak dapat dipindahkan ke universitas di luar scope Leader.'
      using errcode = '42501';
  end if;

  if tg_table_name = 'courses'
     and (
       new.organization_id is distinct from old.organization_id
       or new.program_id is distinct from old.program_id
     )
     and (
       not private.leader_can_access_organization(new.organization_id)
       or not private.leader_can_access_program(new.program_id)
     ) then
    raise exception 'Course tidak dapat dipindahkan ke parent di luar scope Leader.'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_profile_privileged_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.is_active_admin() then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.role is distinct from old.role
     or new.status is distinct from old.status
     or new.created_at is distinct from old.created_at then
    raise exception 'Kolom role, status, id, dan created_at hanya dapat diubah Admin.'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tryout_result(target_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  attempt_row public.tryout_attempts%rowtype;
  tryout_row public.tryouts%rowtype;
  attempt_limit_reached boolean;
  result_visible boolean;
  review_visible boolean;
begin
  select * into attempt_row
  from public.tryout_attempts
  where id = target_attempt_id
    and (
      profile_id = auth.uid()
      or public.current_profile_role() = 'admin'
    );

  if not found then
    raise exception 'Hasil Try Out tidak ditemukan.';
  end if;

  if attempt_row.status = 'in_progress' then
    raise exception 'Try Out belum selesai.';
  end if;

  select * into tryout_row
  from public.tryouts
  where id = attempt_row.tryout_id;

  select count(*) >= tryout_row.max_attempts
  into attempt_limit_reached
  from public.tryout_attempts a
  where a.tryout_id = attempt_row.tryout_id
    and a.profile_id = attempt_row.profile_id
    and a.status in ('submitted', 'expired');

  result_visible :=
    public.current_profile_role() = 'admin'
    or attempt_limit_reached
    or tryout_row.result_release_mode = 'immediate'
    or (
      tryout_row.result_release_mode = 'after_close'
      and tryout_row.close_at is not null
      and now() >= tryout_row.close_at
    );

  if not result_visible then
    return jsonb_build_object(
      'released', false,
      'message', 'Nilai akan tersedia setelah periode Try Out berakhir.'
    );
  end if;

  review_visible :=
    public.current_profile_role() = 'admin'
    or attempt_limit_reached
    or tryout_row.review_release_mode = 'immediate'
    or (
      tryout_row.review_release_mode = 'after_close'
      and tryout_row.close_at is not null
      and now() >= tryout_row.close_at
    );

  return jsonb_build_object(
    'released', true,
    'attempt_id', attempt_row.id,
    'tryout_id', tryout_row.id,
    'title', tryout_row.title,
    'score', attempt_row.score,
    'passing_score', tryout_row.passing_score,
    'passed', attempt_row.score >= tryout_row.passing_score,
    'status', attempt_row.status,
    'total_questions', attempt_row.total_questions,
    'total_correct', attempt_row.total_correct,
    'total_wrong', attempt_row.total_wrong,
    'total_unanswered', attempt_row.total_unanswered,
    'duration_seconds', attempt_row.duration_seconds,
    'review_available', review_visible
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_student_payment_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.is_active_admin() then return new; end if;

  if (select auth.uid()) is null
     or not exists (
       select 1 from public.enrollments e
       where e.id = old.enrollment_id
         and e.profile_id = (select auth.uid())
     ) then
    raise exception 'Pembayaran hanya dapat diubah oleh pemilik atau admin.' using errcode = '42501';
  end if;

  if old.status <> 'rejected'::public.payment_status
     or new.status <> 'pending'::public.payment_status then
    raise exception 'Hanya pembayaran yang ditolak yang dapat dikirim ulang.' using errcode = '42501';
  end if;

  if new.id is distinct from old.id
     or new.enrollment_id is distinct from old.enrollment_id
     or new.created_at is distinct from old.created_at
     or new.payment_account_id is distinct from old.payment_account_id
     or new.bank_name_snapshot is distinct from old.bank_name_snapshot
     or new.account_number_snapshot is distinct from old.account_number_snapshot
     or new.account_holder_name_snapshot is distinct from old.account_holder_name_snapshot
     or new.payment_account_label_snapshot is distinct from old.payment_account_label_snapshot then
    raise exception 'Identitas pembayaran dan snapshot rekening tidak boleh diubah peserta.' using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.course_id_from_storage_path(object_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  first_segment TEXT;
BEGIN
  first_segment := split_part(object_name, '/', 1);

  IF first_segment !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    RETURN NULL;
  END IF;

  RETURN first_segment::UUID;
END;
$function$

CREATE OR REPLACE FUNCTION private.protect_profile_sensitive_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'Profile ID tidak dapat diubah.'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Waktu pembuatan profile tidak dapat diubah.'
      USING ERRCODE = '42501';
  END IF;

  IF NOT private.is_active_admin()
     AND COALESCE((SELECT auth.role()), '') <> 'service_role'
     AND (
       NEW.role IS DISTINCT FROM OLD.role
       OR NEW.status IS DISTINCT FROM OLD.status
     ) THEN
    RAISE EXCEPTION 'Role dan status akun hanya dapat diubah oleh admin aktif.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_zero_payment_enrollment(target_enrollment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_profile_id UUID := (SELECT auth.uid());
  enrollment_record public.enrollments%ROWTYPE;
  payment_record public.payments%ROWTYPE;
  final_amount NUMERIC := 0;
BEGIN
  IF current_profile_id IS NULL THEN
    RAISE EXCEPTION 'Silakan masuk terlebih dahulu.' USING ERRCODE = '42501';
  END IF;
  IF NOT private.is_active_student() THEN
    RAISE EXCEPTION 'Hanya peserta aktif yang dapat mengirim pendaftaran.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO enrollment_record
  FROM public.enrollments
  WHERE id = target_enrollment_id AND profile_id = current_profile_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Enrollment tidak ditemukan.' USING ERRCODE = 'P0002';
  END IF;
  IF enrollment_record.status <> 'pending_payment'::public.enrollment_status THEN
    RAISE EXCEPTION 'Enrollment ini sudah dikirim atau tidak dapat diproses.' USING ERRCODE = '22023';
  END IF;
  final_amount := GREATEST(enrollment_record.price_snapshot - enrollment_record.discount_amount, 0);
  IF final_amount <> 0 THEN
    RAISE EXCEPTION 'Enrollment ini masih memiliki nominal pembayaran.' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO payment_record
  FROM public.payments
  WHERE enrollment_id = enrollment_record.id
  FOR UPDATE;
  IF FOUND THEN
    IF payment_record.status = 'approved'::public.payment_status THEN
      RAISE EXCEPTION 'Pembayaran sudah disetujui.' USING ERRCODE = '22023';
    END IF;
    UPDATE public.payments
    SET amount = 0,
        payment_method = 'free'::public.payment_method,
        payment_proof_path = NULL,
        status = 'pending'::public.payment_status,
        paid_at = NOW(),
        verified_at = NULL,
        verified_by = NULL,
        notes = NULL,
        updated_at = NOW()
    WHERE id = payment_record.id;
  ELSE
    INSERT INTO public.payments (
      enrollment_id, amount, payment_method, payment_proof_path, status, paid_at
    ) VALUES (
      enrollment_record.id, 0, 'free'::public.payment_method, NULL, 'pending'::public.payment_status, NOW()
    );
  END IF;
  UPDATE public.enrollments
  SET status = 'pending_approval'::public.enrollment_status,
      activated_at = NULL,
      updated_at = NOW()
  WHERE id = enrollment_record.id;
  RETURN jsonb_build_object(
    'enrollment_id', enrollment_record.id,
    'status', 'pending_approval',
    'amount', 0
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_default_payment_account(target_account_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (select public.current_profile_role()) <> 'admin' then
    raise exception 'Akses Admin diperlukan.';
