CREATE OR REPLACE FUNCTION public.guard_tryout_image_path_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_course_id uuid;
  plain_question_pattern text;
  r2_question_pattern text;
  plain_explanation_pattern text;
  r2_explanation_pattern text;
begin
  select t.course_id
  into target_course_id
  from public.tryouts t
  where t.id = new.tryout_id;

  if target_course_id is null then
    raise exception 'Course Try Out tidak ditemukan.' using errcode = '23503';
  end if;

  new.image_path := nullif(btrim(new.image_path), '');
  new.explanation_image_path := nullif(btrim(new.explanation_image_path), '');

  plain_question_pattern :=
    '^' || target_course_id::text || '/(quiz-images|tryout-images)/' ||
    new.tryout_id::text || '/question/[^/]+$';
  r2_question_pattern :=
    '^r2://[^/]+/courses/' || target_course_id::text ||
    '/(quiz-images|tryout-images)/' || new.tryout_id::text ||
    '/question/[^/]+$';
  plain_explanation_pattern :=
    '^' || target_course_id::text || '/(quiz-images|tryout-images)/' ||
    new.tryout_id::text || '/explanation/[^/]+$';
  r2_explanation_pattern :=
    '^r2://[^/]+/courses/' || target_course_id::text ||
    '/(quiz-images|tryout-images)/' || new.tryout_id::text ||
    '/explanation/[^/]+$';

  if new.image_path is not null
     and (
       position('..' in new.image_path) > 0
       or (
         new.image_path !~ plain_question_pattern
         and new.image_path !~ r2_question_pattern
       )
       or lower(new.image_path) !~ E'\\.(jpg|jpeg|png|webp)$'
     ) then
    raise exception 'Path gambar soal tidak sesuai Course, Try Out, atau format gambar.'
      using errcode = '22023';
  end if;

  if new.explanation_image_path is not null
     and (
       position('..' in new.explanation_image_path) > 0
       or (
         new.explanation_image_path !~ plain_explanation_pattern
         and new.explanation_image_path !~ r2_explanation_pattern
       )
       or lower(new.explanation_image_path) !~ E'\\.(jpg|jpeg|png|webp)$'
     ) then
    raise exception 'Path gambar pembahasan tidak sesuai Course, Try Out, atau format gambar.'
      using errcode = '22023';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_course_mentors(target_course_id uuid, target_mentor_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_count integer;
  valid_count integer;
begin
  if not private.is_active_admin() then
    raise exception 'Hanya admin aktif yang dapat mengatur mentor course.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.courses where id = target_course_id) then
    raise exception 'Course tidak ditemukan.' using errcode = 'P0002';
  end if;

  select count(distinct mentor_id)::integer
    into requested_count
  from unnest(coalesce(target_mentor_ids, array[]::uuid[])) as requested(mentor_id);

  select count(distinct md.id)::integer
    into valid_count
  from public.mentor_details md
  join public.profiles profile on profile.id = md.profile_id
  where md.id = any(coalesce(target_mentor_ids, array[]::uuid[]))
    and profile.role = 'mentor'
    and profile.status = 'active';

  if requested_count <> valid_count then
    raise exception 'Satu atau lebih mentor tidak valid atau tidak aktif.' using errcode = '22023';
  end if;

  update public.course_mentors
  set is_active = false,
      removed_at = now()
  where course_id = target_course_id
    and is_active
    and not (mentor_id = any(coalesce(target_mentor_ids, array[]::uuid[])));

  insert into public.course_mentors (course_id, mentor_id, is_active, removed_at)
  select target_course_id, mentor_id, true, null
  from (
    select distinct mentor_id
    from unnest(coalesce(target_mentor_ids, array[]::uuid[])) as requested(mentor_id)
  ) requested_mentors
  on conflict (course_id, mentor_id)
  do update set is_active = true, removed_at = null;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_payment_account_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_account public.payment_accounts%rowtype;
begin
  if tg_op = 'UPDATE' then
    if new.enrollment_id is distinct from old.enrollment_id
       or new.payment_account_id is distinct from old.payment_account_id
       or new.bank_name_snapshot is distinct from old.bank_name_snapshot
       or new.account_number_snapshot is distinct from old.account_number_snapshot
       or new.account_holder_name_snapshot is distinct from old.account_holder_name_snapshot then
      raise exception 'Identitas enrollment dan snapshot rekening pembayaran tidak dapat diubah.'
        using errcode = '42501';
    end if;
    return new;
  end if;

  select pa.*
  into target_account
  from public.enrollments e
  join public.courses c on c.id = e.course_id
  join public.payment_accounts pa on pa.id = c.payment_account_id
  where e.id = new.enrollment_id
    and pa.is_active;

  if not found then
    raise exception 'Rekening aktif untuk course pembayaran tidak tersedia.'
      using errcode = 'P0002';
  end if;

  new.payment_account_id := target_account.id;
  new.bank_name_snapshot := target_account.bank_name;
  new.account_number_snapshot := target_account.account_number;
  new.account_holder_name_snapshot := target_account.account_holder_name;

  return new;
end;
$function$

