CREATE OR REPLACE FUNCTION public.save_tryout_answer(target_attempt_id uuid, target_question_id uuid, target_option_id uuid, marked_for_review boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  attempt_row public.tryout_attempts%rowtype;
begin
  select * into attempt_row
  from public.tryout_attempts
  where id = target_attempt_id
    and profile_id = auth.uid()
  for update;

  if not found then
    raise exception 'Attempt Try Out tidak ditemukan.';
  end if;

  if attempt_row.status <> 'in_progress' then
    raise exception 'Attempt Try Out sudah selesai.';
  end if;

  if attempt_row.expires_at <= now() then
    perform public.finalize_tryout_attempt(attempt_row.id, 'expired');
    raise exception 'Waktu Try Out telah habis.';
  end if;

  if not (target_question_id = any(attempt_row.question_order)) then
    raise exception 'Soal tidak termasuk dalam attempt ini.';
  end if;

  if target_option_id is not null and not exists (
    select 1 from public.tryout_options o
    where o.id = target_option_id
      and o.question_id = target_question_id
  ) then
    raise exception 'Pilihan jawaban tidak valid.';
  end if;

  insert into public.tryout_answers (
    attempt_id,
    question_id,
    selected_option_id,
    is_marked_for_review,
    answered_at
  ) values (
    target_attempt_id,
    target_question_id,
    target_option_id,
    marked_for_review,
    case when target_option_id is null then null else now() end
  )
  on conflict (attempt_id, question_id)
  do update set
    selected_option_id = excluded.selected_option_id,
    is_marked_for_review = excluded.is_marked_for_review,
    answered_at = excluded.answered_at,
    updated_at = now();

  return jsonb_build_object('success', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.start_tryout_attempt(target_tryout_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  tryout_row public.tryouts%rowtype;
  existing_attempt public.tryout_attempts%rowtype;
  new_attempt public.tryout_attempts%rowtype;
  next_attempt integer;
  question_ids uuid[];
  options_snapshot jsonb;
begin
  if auth.uid() is null or public.current_profile_role() <> 'student' then
    raise exception 'Hanya peserta yang dapat memulai Try Out.';
  end if;

  select * into tryout_row
  from public.tryouts
  where id = target_tryout_id;

  if not found then
    raise exception 'Try Out tidak ditemukan.';
  end if;

  if tryout_row.publication_status not in ('scheduled', 'published') then
    raise exception 'Try Out belum tersedia.';
  end if;

  if tryout_row.open_at is not null and now() < tryout_row.open_at then
    raise exception 'Try Out belum dibuka.';
  end if;

  if tryout_row.close_at is not null and now() >= tryout_row.close_at then
    raise exception 'Periode Try Out telah berakhir.';
  end if;

  if not exists (
    select 1 from public.enrollments e
    where e.profile_id = auth.uid()
      and e.course_id = tryout_row.course_id
      and e.status = 'active'
      and (e.expired_at is null or e.expired_at > now())
  ) then
    raise exception 'Anda tidak memiliki akses aktif ke course ini.';
  end if;

  select * into existing_attempt
  from public.tryout_attempts
  where tryout_id = target_tryout_id
    and profile_id = auth.uid()
    and status = 'in_progress'
  order by started_at desc
  limit 1;

  if found then
    if existing_attempt.expires_at <= now() then
      perform public.finalize_tryout_attempt(existing_attempt.id, 'expired');
    else
      return jsonb_build_object(
        'attempt_id', existing_attempt.id,
        'resumed', true
      );
    end if;
  end if;

  select coalesce(max(attempt_number), 0) + 1
  into next_attempt
  from public.tryout_attempts
  where tryout_id = target_tryout_id
    and profile_id = auth.uid();

  if next_attempt > tryout_row.max_attempts then
    raise exception 'Batas percobaan Try Out telah habis.';
  end if;

  if not exists (
    select 1 from public.tryout_questions q
    where q.tryout_id = target_tryout_id
  ) then
    raise exception 'Soal Try Out belum tersedia.';
  end if;

  if exists (
    select 1
    from public.tryout_questions q
    left join public.tryout_options o on o.question_id = q.id
    where q.tryout_id = target_tryout_id
    group by q.id
    having count(o.id) < 2
       or count(o.id) filter (where o.is_correct) <> 1
  ) then
    raise exception 'Setiap soal harus memiliki minimal dua opsi dan tepat satu jawaban benar.';
  end if;

  select array_agg(q.id order by
    case when tryout_row.shuffle_questions then random() else q.question_order::double precision end
  )
  into question_ids
  from public.tryout_questions q
  where q.tryout_id = target_tryout_id;

  select coalesce(jsonb_object_agg(snapshot.question_id::text, snapshot.option_ids), '{}'::jsonb)
  into options_snapshot
  from (
    select
      q.id as question_id,
      (
        select jsonb_agg(o.id order by
          case when tryout_row.shuffle_options then random() else o.option_order::double precision end
        )
        from public.tryout_options o
        where o.question_id = q.id
      ) as option_ids
    from public.tryout_questions q
    where q.tryout_id = target_tryout_id
  ) snapshot;

  insert into public.tryout_attempts (
    tryout_id,
    profile_id,
    attempt_number,
    expires_at,
    question_order,
    option_orders
  ) values (
    target_tryout_id,
    auth.uid(),
    next_attempt,
    now() + make_interval(mins => tryout_row.duration_minutes),
    question_ids,
    options_snapshot
  )
  returning * into new_attempt;

  return jsonb_build_object(
    'attempt_id', new_attempt.id,
    'resumed', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_tryout_attempt(target_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  attempt_row public.tryout_attempts%rowtype;
  final_state text;
begin
  select * into attempt_row
  from public.tryout_attempts
  where id = target_attempt_id
    and profile_id = auth.uid();

  if not found then
    raise exception 'Attempt Try Out tidak ditemukan.';
  end if;

  final_state := case
    when attempt_row.expires_at <= now() then 'expired'
    else 'submitted'
  end;

  return public.finalize_tryout_attempt(attempt_row.id, final_state);
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_course_payment_account_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1
    from public.payment_accounts pa
    where pa.id = new.payment_account_id
      and pa.is_active
  ) then
    raise exception 'Course wajib menggunakan rekening pembayaran aktif.'
      using errcode = '23503';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.normalize_payment_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.bank_name := btrim(new.bank_name);
  new.account_number := regexp_replace(new.account_number, '[^0-9]', '', 'g');
  new.account_holder_name := btrim(new.account_holder_name);

  if char_length(new.bank_name) < 2
     or char_length(new.account_number) < 6
     or char_length(new.account_holder_name) < 2 then
    raise exception 'Data rekening pembayaran tidak valid.' using errcode = '22023';
  end if;

  if new.is_default and not new.is_active then
    raise exception 'Rekening default harus aktif.' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_course_payment_account(target_course_id uuid, target_payment_account_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_active_admin() then
    raise exception 'Hanya Admin aktif yang dapat mengatur rekening course.'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.payment_accounts pa
    where pa.id = target_payment_account_id
      and pa.is_active
  ) then
    raise exception 'Rekening pembayaran aktif tidak ditemukan.'
      using errcode = 'P0002';
  end if;

  update public.courses
  set payment_account_id = target_payment_account_id,
      updated_at = now()
  where id = target_course_id;

  if not found then
    raise exception 'Course tidak ditemukan.' using errcode = 'P0002';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_default_payment_account(target_payment_account_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_active_admin() then
    raise exception 'Hanya Admin aktif yang dapat mengatur rekening default.'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.payment_accounts pa
    where pa.id = target_payment_account_id
      and pa.is_active
  ) then
    raise exception 'Rekening pembayaran aktif tidak ditemukan.'
      using errcode = 'P0002';
  end if;

  update public.payment_accounts
  set is_default = false
  where is_default
    and id <> target_payment_account_id;

  update public.payment_accounts
  set is_default = true,
      is_active = true
  where id = target_payment_account_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.can_manage_tryout_image_object(object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_course_id uuid;
  target_tryout_id uuid;
  folder_segment text;
  tryout_segment text;
  image_kind text;
  file_name text;
begin
  target_course_id := private.course_id_from_storage_path(object_name);
  folder_segment := split_part(object_name, '/', 2);
  tryout_segment := split_part(object_name, '/', 3);
  image_kind := split_part(object_name, '/', 4);
  file_name := split_part(object_name, '/', 5);

  if target_course_id is null
     or folder_segment not in ('quiz-images', 'tryout-images')
     or tryout_segment !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or image_kind not in ('question', 'explanation')
     or file_name = ''
     or split_part(object_name, '/', 6) <> ''
     or position('..' in object_name) > 0
     or lower(file_name) !~ '\.(jpg|jpeg|png|webp)$' then
    return false;
  end if;

  target_tryout_id := tryout_segment::uuid;

  return exists (
    select 1
    from public.tryouts t
    where t.id = target_tryout_id
      and t.course_id = target_course_id
      and (
        private.is_active_admin()
        or (
          (select public.current_profile_role()) = 'mentor'::public.profile_role
          and t.created_by = (select auth.uid())
          and public.is_assigned_mentor((select auth.uid()), t.course_id)
        )
      )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_student_account(target_profile_id uuid, confirmation_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'private', 'pg_temp'
AS $function$
declare
  target_email text;
  target_role text;
begin
  if not private.is_active_admin() then
    raise exception 'Anda tidak memiliki izin sebagai admin.'
      using errcode = '42501';
  end if;

  if target_profile_id is null then
    raise exception 'Akun mahasiswa tidak ditemukan.'
      using errcode = '22023';
  end if;

  if nullif(btrim(confirmation_email), '') is null then
    raise exception 'Email konfirmasi wajib diisi.'
      using errcode = '22023';
  end if;

  select u.email::text, p.role::text
  into target_email, target_role
  from auth.users u
  join public.profiles p on p.id = u.id
  where u.id = target_profile_id
  for update of u, p;

  if not found then
    raise exception 'Akun mahasiswa tidak ditemukan.'
      using errcode = 'P0002';
  end if;

  if target_role <> 'student' then
    raise exception 'Hanya akun mahasiswa yang dapat dihapus dari menu ini.'
      using errcode = '42501';
  end if;

  if lower(btrim(coalesce(target_email, ''))) <> lower(btrim(confirmation_email)) then
    raise exception 'Email konfirmasi tidak sesuai.'
      using errcode = '22023';
  end if;

  delete from auth.users
  where id = target_profile_id;

  if not found then
    raise exception 'Akun mahasiswa gagal dihapus.';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.mentor_get_course_reviews(target_course_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare current_id uuid:=auth.uid(); target_mentor_id uuid; result jsonb;
begin
  select md.id into target_mentor_id from public.mentor_details md join public.profiles p on p.id=md.profile_id
  where md.profile_id=current_id and p.role='mentor' and p.status='active';
  if target_mentor_id is null then raise exception 'Mentor aktif tidak ditemukan.' using errcode='42501'; end if;
  if not exists(select 1 from public.course_mentors where mentor_id=target_mentor_id and course_id=target_course_id) then raise exception 'Course tidak ditemukan pada riwayat penugasan.' using errcode='42501'; end if;

  select jsonb_build_object(
    'courseId',c.id,'courseTitle',c.title,
    'averageRating',coalesce((select round(avg(rating)::numeric,2) from public.mentor_reviews where mentor_id=target_mentor_id and course_id=c.id),0),
    'ratingCount',(select count(*) from public.mentor_reviews where mentor_id=target_mentor_id and course_id=c.id),
    'reviews',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',mr.id,'reviewerName',case when mr.reviewer_type='admin' then 'Admin' else p.full_name end,
        'reviewerType',mr.reviewer_type,'rating',mr.rating,'suggestion',mr.suggestion,'updatedAt',mr.updated_at
      ) order by mr.updated_at desc)
      from public.mentor_reviews mr join public.profiles p on p.id=mr.reviewer_profile_id
      where mr.mentor_id=target_mentor_id and mr.course_id=c.id
    ),'[]'::jsonb)
  ) into result from public.courses c where c.id=target_course_id;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.mentor_get_rating_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare current_id uuid:=auth.uid(); target_mentor_id uuid; result jsonb;
begin
  select md.id into target_mentor_id from public.mentor_details md join public.profiles p on p.id=md.profile_id
  where md.profile_id=current_id and p.role='mentor' and p.status='active';
  if target_mentor_id is null then raise exception 'Mentor aktif tidak ditemukan.' using errcode='42501'; end if;

  select jsonb_build_object(
    'overallAverage',coalesce((select round(avg(rating)::numeric,2) from public.mentor_reviews where mentor_id=target_mentor_id),0),
    'totalRatings',(select count(*) from public.mentor_reviews where mentor_id=target_mentor_id),
    'courses',coalesce((
      select jsonb_agg(jsonb_build_object(
        'courseId',c.id,'courseTitle',c.title,'organizationTitle',o.title,'programTitle',pr.title,
        'isActive',cm.is_active,'averageRating',coalesce(rs.avg_rating,0),'ratingCount',coalesce(rs.rating_count,0)
      ) order by cm.is_active desc,o.title,c.title)
      from public.course_mentors cm
      join public.courses c on c.id=cm.course_id
      join public.organizations o on o.id=c.organization_id
      join public.programs pr on pr.id=c.program_id
      left join lateral(select round(avg(rating)::numeric,2) avg_rating,count(*) rating_count from public.mentor_reviews where mentor_id=target_mentor_id and course_id=c.id) rs on true
      where cm.mentor_id=target_mentor_id
    ),'[]'::jsonb)
  ) into result;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_course_mentor_rating_context(target_course_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare current_id uuid := auth.uid(); result jsonb;
begin
  if current_id is null then raise exception 'Silakan masuk terlebih dahulu.' using errcode='42501'; end if;
  if not private.is_active_admin() and not exists(
    select 1 from public.enrollments e where e.profile_id=current_id and e.course_id=target_course_id and e.status='active'
  ) then
    raise exception 'Anda tidak memiliki akses ke course ini.' using errcode='42501';
  end if;

  select jsonb_build_object(
    'enabled',c.mentor_rating_enabled,
    'mentors',coalesce((
      select jsonb_agg(jsonb_build_object(
        'mentorId',md.id,'profileId',p.id,'fullName',p.full_name,
        'rating',mr.rating,'suggestion',mr.suggestion
      ) order by p.full_name)
      from public.course_mentors cm
      join public.mentor_details md on md.id=cm.mentor_id
      join public.profiles p on p.id=md.profile_id
      left join public.mentor_reviews mr on mr.mentor_id=md.id and mr.course_id=target_course_id and mr.reviewer_profile_id=current_id
      where cm.course_id=target_course_id
        and cm.is_active
        and cm.show_in_rating
        and p.status='active'
    ),'[]'::jsonb)
  ) into result
  from public.courses c where c.id=target_course_id;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_mentor_review(target_course_id uuid, target_mentor_id uuid, target_rating integer, target_suggestion text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_profile_id uuid := auth.uid();
  v_profile_role public.profile_role;
begin
  if v_profile_id is null then
    raise exception 'Silakan masuk terlebih dahulu.' using errcode='42501';
  end if;

  if target_rating < 1 or target_rating > 5 then
    raise exception 'Nilai bintang harus 1 sampai 5.';
  end if;

  if target_suggestion is not null and char_length(target_suggestion) > 500 then
    raise exception 'Saran maksimal 500 karakter.';
  end if;

  select p.role into v_profile_role
  from public.profiles p
  where p.id = v_profile_id and p.status = 'active';

  if v_profile_role is null or v_profile_role not in ('admin'::public.profile_role, 'student'::public.profile_role) then
    raise exception 'Anda tidak dapat memberikan penilaian.' using errcode='42501';
  end if;

  if not exists (
    select 1 from public.courses c
    where c.id = target_course_id and c.mentor_rating_enabled
  ) then
    raise exception 'Penilaian mentor sedang dinonaktifkan.';
  end if;

  if not exists (
    select 1 from public.course_mentors cm
    where cm.course_id = target_course_id
      and cm.mentor_id = target_mentor_id
      and cm.is_active
      and cm.show_in_rating
  ) then
    raise exception 'Mentor tidak dipilih untuk penilaian pada course ini.';
  end if;

  if v_profile_role = 'student'::public.profile_role and not exists (
    select 1 from public.enrollments e
    where e.profile_id = v_profile_id
      and e.course_id = target_course_id
      and e.status = 'active'
      and (e.expired_at is null or e.expired_at > now())
  ) then
    raise exception 'Enrollment aktif diperlukan untuk menilai mentor.' using errcode='42501';
  end if;

  insert into public.mentor_reviews(
    mentor_id, course_id, reviewer_profile_id, reviewer_type, rating, suggestion
  ) values(
    target_mentor_id,
    target_course_id,
    v_profile_id,
    case when v_profile_role = 'admin'::public.profile_role then 'admin' else 'student' end,
    target_rating,
    nullif(trim(coalesce(target_suggestion,'')),'')
  )
  on conflict(mentor_id,course_id,reviewer_profile_id)
  do update set
    rating=excluded.rating,
    suggestion=excluded.suggestion,
    reviewer_type=excluded.reviewer_type,
    updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_mentor_assignment(target_profile_id uuid, target_course_id uuid, target_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare target_mentor_id uuid;
begin
  if not private.is_active_admin() then
    raise exception 'Anda tidak memiliki izin sebagai admin.' using errcode='42501';
  end if;

  select md.id into target_mentor_id
  from public.mentor_details md
  join public.profiles p on p.id=md.profile_id
  where md.profile_id=target_profile_id and p.role='mentor';

  if target_mentor_id is null then raise exception 'Mentor tidak ditemukan.'; end if;
  if not exists(select 1 from public.courses where id=target_course_id) then raise exception 'Course tidak ditemukan.'; end if;

  if target_active then
    insert into public.course_mentors(course_id,mentor_id,is_active,removed_at,show_in_rating)
    values(target_course_id,target_mentor_id,true,null,true)
    on conflict(course_id,mentor_id) do update
      set is_active=true, removed_at=null, show_in_rating=true;
  else
    update public.course_mentors
    set is_active=false, removed_at=now()
    where course_id=target_course_id and mentor_id=target_mentor_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_course_rating_mentors(target_course_id uuid, target_mentor_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  selected_ids uuid[] := coalesce(target_mentor_ids, '{}'::uuid[]);
begin
  if not private.is_active_admin() then
    raise exception 'Anda tidak memiliki izin sebagai admin.' using errcode='42501';
  end if;

  if not exists(select 1 from public.courses c where c.id=target_course_id) then
    raise exception 'Course tidak ditemukan.';
  end if;

  if exists (
    select 1
    from unnest(selected_ids) selected(mentor_id)
    where not exists (
      select 1 from public.course_mentors cm
      where cm.course_id=target_course_id
        and cm.mentor_id=selected.mentor_id
        and cm.is_active
    )
  ) then
    raise exception 'Ada mentor yang tidak ditugaskan aktif pada course ini.';
  end if;

  update public.course_mentors cm
  set show_in_rating = cm.mentor_id = any(selected_ids)
  where cm.course_id=target_course_id
    and cm.is_active;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_review_payment(target_payment_id uuid, target_status payment_status, rejection_notes text DEFAULT NULL::text)
 RETURNS payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payment_record public.payments%rowtype;
  enrollment_record public.enrollments%rowtype;
  normalized_notes text := nullif(btrim(coalesce(rejection_notes, '')), '');
begin
  if not private.is_active_admin() then
    raise exception 'Akses Admin diperlukan.' using errcode = '42501';
  end if;

  if target_status not in ('approved'::public.payment_status, 'rejected'::public.payment_status) then
    raise exception 'Status review pembayaran tidak valid.' using errcode = '22023';
  end if;

  select * into payment_record
  from public.payments
  where id = target_payment_id
  for update;

  if not found then
    raise exception 'Payment tidak ditemukan.' using errcode = 'P0002';
  end if;

  if payment_record.status <> 'pending'::public.payment_status then
    raise exception 'Hanya payment yang menunggu verifikasi yang dapat direview.' using errcode = '22023';
  end if;

  select * into enrollment_record
  from public.enrollments
  where id = payment_record.enrollment_id
  for update;

  if not found then
    raise exception 'Enrollment pembayaran tidak ditemukan.' using errcode = 'P0002';
  end if;

  update public.payments
  set status = target_status,
      verified_by = (select auth.uid()),
      verified_at = now(),
      notes = case when target_status = 'rejected'::public.payment_status then normalized_notes else null end,
      updated_at = now()
  where id = payment_record.id
  returning * into payment_record;

  if enrollment_record.payment_timing = 'upfront'::public.payment_timing then
    if target_status = 'approved'::public.payment_status then
      update public.enrollments
      set status = 'active'::public.enrollment_status,
          activated_at = coalesce(activated_at, now()),
          updated_at = now()
      where id = enrollment_record.id;
    else
      update public.enrollments
      set status = 'pending_payment'::public.enrollment_status,
          activated_at = null,
          updated_at = now()
      where id = enrollment_record.id;
    end if;
  end if;

  insert into public.activity_logs (
    profile_id, action, entity_type, entity_id, description
  ) values (
    (select auth.uid()),
    case when target_status = 'approved'::public.payment_status then 'approve_payment' else 'reject_payment' end,
    'payment',
    payment_record.id,
    format('Payment %s untuk enrollment %s.', target_status, enrollment_record.id)
  );

  return payment_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_enrollment_payment_timing(target_enrollment_id uuid, target_payment_timing payment_timing)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  enrollment_record public.enrollments%rowtype;
  current_payment_status public.payment_status;
  next_status public.enrollment_status;
  next_activated_at timestamptz;
begin
  if not private.is_active_admin() then
    raise exception 'Akses Admin diperlukan.' using errcode = '42501';
  end if;

  select * into enrollment_record
  from public.enrollments
  where id = target_enrollment_id
  for update;

  if not found then
    raise exception 'Enrollment tidak ditemukan.' using errcode = 'P0002';
  end if;

  if enrollment_record.status in ('cancelled'::public.enrollment_status, 'expired'::public.enrollment_status) then
    raise exception 'Kategori pembayaran enrollment yang sudah berakhir tidak dapat diubah.' using errcode = '22023';
  end if;

  if enrollment_record.payment_timing = target_payment_timing then
    return;
  end if;

  if target_payment_timing = 'deferred'::public.payment_timing
     and not exists (
       select 1
       from public.courses c
       where c.id = enrollment_record.course_id
         and c.payment_policy = 'upfront_or_deferred'::public.payment_policy
     ) then
    raise exception 'Course ini tidak menyediakan pembayaran di akhir.' using errcode = '22023';
  end if;

  select p.status into current_payment_status
  from public.payments p
  where p.enrollment_id = enrollment_record.id;

  if target_payment_timing = 'deferred'::public.payment_timing then
    if enrollment_record.status = 'active'::public.enrollment_status
       or current_payment_status = 'approved'::public.payment_status then
      next_status := 'active'::public.enrollment_status;
      next_activated_at := coalesce(enrollment_record.activated_at, now());
    else
      next_status := 'pending_approval'::public.enrollment_status;
      next_activated_at := null;
    end if;
  else
    if current_payment_status = 'approved'::public.payment_status then
      next_status := 'active'::public.enrollment_status;
      next_activated_at := coalesce(enrollment_record.activated_at, now());
    elsif current_payment_status = 'pending'::public.payment_status then
      next_status := 'pending_approval'::public.enrollment_status;
      next_activated_at := null;
    else
      next_status := 'pending_payment'::public.enrollment_status;
      next_activated_at := null;
    end if;
  end if;

  update public.enrollments
  set payment_timing = target_payment_timing,
      status = next_status,
      activated_at = next_activated_at,
      updated_at = now()
  where id = enrollment_record.id;

  insert into public.activity_logs (
    profile_id, action, entity_type, entity_id, description
  ) values (
    (select auth.uid()),
    'update_payment_timing',
    'enrollment',
    enrollment_record.id,
    format(
      'Payment timing diubah dari %s menjadi %s; status enrollment %s menjadi %s.',
      enrollment_record.payment_timing,
      target_payment_timing,
      enrollment_record.status,
      next_status
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_deferred_promotion_code(target_enrollment_id uuid, submitted_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_profile_id uuid := (select auth.uid());
  normalized_code text := upper(btrim(coalesce(submitted_code, '')));
  enrollment_record public.enrollments%rowtype;
  promotion_record public.promotions%rowtype;
  active_usage_count integer := 0;
  profile_usage_count integer := 0;
  calculated_discount numeric := 0;
  final_amount numeric := 0;
begin
  if current_profile_id is null then
    raise exception 'Silakan masuk terlebih dahulu.' using errcode = '42501';
  end if;

  if not private.is_active_student() then
    raise exception 'Hanya peserta aktif yang dapat memakai kode promosi.'
      using errcode = '42501';
  end if;

  if normalized_code = '' then
    raise exception 'Kode promosi wajib diisi.' using errcode = '22023';
  end if;

  select *
  into enrollment_record
  from public.enrollments
  where id = target_enrollment_id
    and profile_id = current_profile_id
  for update;

  if not found then
    raise exception 'Enrollment tidak ditemukan.' using errcode = 'P0002';
  end if;

  if enrollment_record.payment_timing <> 'deferred'::public.payment_timing
     or enrollment_record.status <> 'active'::public.enrollment_status then
    raise exception 'Kode promosi pembayaran akhir hanya tersedia pada enrollment aktif.'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.payments p
    where p.enrollment_id = enrollment_record.id
      and p.status in (
        'pending'::public.payment_status,
        'approved'::public.payment_status
      )
  ) then
    raise exception 'Kode promosi tidak dapat diubah setelah pembayaran dikirim.'
      using errcode = '22023';
  end if;

  select *
  into promotion_record
  from public.promotions
  where code is not null
    and upper(btrim(code)) = normalized_code
  order by priority asc, created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'Kode promosi tidak ditemukan.' using errcode = 'P0002';
  end if;

  if promotion_record.status <> 'active'::public.promotion_status then
    raise exception 'Kode promosi sedang tidak aktif.' using errcode = '22023';
  end if;

  if promotion_record.start_at > now() then
    raise exception 'Kode promosi belum dapat digunakan.' using errcode = '22023';
  end if;

  if promotion_record.end_at is not null
     and promotion_record.end_at < now() then
    raise exception 'Kode promosi sudah berakhir.' using errcode = '22023';
  end if;

  if promotion_record.course_id is not null
     and promotion_record.course_id <> enrollment_record.course_id then
    raise exception 'Kode promosi tidak berlaku untuk course ini.'
      using errcode = '22023';
  end if;

  if enrollment_record.price_snapshot < coalesce(promotion_record.minimum_purchase, 0) then
    raise exception 'Harga course belum memenuhi minimum transaksi promosi.'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into active_usage_count
  from public.enrollments
  where promotion_id = promotion_record.id
    and id <> enrollment_record.id
    and status not in (
      'cancelled'::public.enrollment_status,
      'expired'::public.enrollment_status
    );

  if promotion_record.quota is not null
     and greatest(promotion_record.used_count, active_usage_count) >= promotion_record.quota then
    raise exception 'Kuota kode promosi sudah habis.' using errcode = '22023';
  end if;

  select count(*)::integer
  into profile_usage_count
  from public.enrollments
  where promotion_id = promotion_record.id
    and profile_id = current_profile_id
    and id <> enrollment_record.id
    and status not in (
      'cancelled'::public.enrollment_status,
      'expired'::public.enrollment_status
    );

  if profile_usage_count >= promotion_record.usage_per_user then
    raise exception 'Batas penggunaan kode promosi untuk akun ini sudah tercapai.'
      using errcode = '22023';
  end if;

  calculated_discount := case promotion_record.type
    when 'percentage'::public.promotion_type then
      round(enrollment_record.price_snapshot * promotion_record.value / 100, 2)
    when 'fixed_amount'::public.promotion_type then
      promotion_record.value
    when 'special_price'::public.promotion_type then
      greatest(
        enrollment_record.price_snapshot
          - coalesce(promotion_record.special_price, promotion_record.value),
        0
      )
    when 'free'::public.promotion_type then
      enrollment_record.price_snapshot
    else 0
  end;

  if promotion_record.max_discount is not null then
    calculated_discount := least(calculated_discount, promotion_record.max_discount);
  end if;

  calculated_discount := least(
    greatest(calculated_discount, 0),
    enrollment_record.price_snapshot
  );
  final_amount := greatest(
    enrollment_record.price_snapshot - calculated_discount,
    0
  );

  perform set_config('app.promotion_checkout', 'on', true);

  update public.enrollments
  set promotion_id = promotion_record.id,
      promotion_code_snapshot = promotion_record.code,
      promotion_name_snapshot = promotion_record.name,
      discount_amount = calculated_discount,
      updated_at = now()
  where id = enrollment_record.id;

  return jsonb_build_object(
    'promotion_id', promotion_record.id,
    'promotion_code', promotion_record.code,
    'promotion_name', promotion_record.name,
    'discount_amount', calculated_discount,
    'final_amount', final_amount
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_deferred_zero_payment(target_enrollment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_profile_id uuid := (select auth.uid());
  enrollment_record public.enrollments%rowtype;
  payment_record public.payments%rowtype;
  final_amount numeric := 0;
begin
  if current_profile_id is null or not private.is_active_student() then
    raise exception 'Hanya peserta aktif yang dapat mengirim pembayaran.'
      using errcode = '42501';
  end if;

  select *
  into enrollment_record
  from public.enrollments
  where id = target_enrollment_id
    and profile_id = current_profile_id
  for update;

  if not found then
    raise exception 'Enrollment tidak ditemukan.' using errcode = 'P0002';
  end if;

  if enrollment_record.payment_timing <> 'deferred'::public.payment_timing
     or enrollment_record.status <> 'active'::public.enrollment_status then
    raise exception 'Pembayaran akhir hanya tersedia pada enrollment aktif.'
      using errcode = '22023';
  end if;

  final_amount := greatest(
    enrollment_record.price_snapshot - enrollment_record.discount_amount,
    0
  );

  if final_amount <> 0 then
    raise exception 'Enrollment ini masih memiliki nominal pembayaran.'
      using errcode = '22023';
  end if;

  select *
  into payment_record
  from public.payments
  where enrollment_id = enrollment_record.id
  for update;

  if found then
    if payment_record.status = 'approved'::public.payment_status then
      raise exception 'Pembayaran sudah disetujui.' using errcode = '22023';
    end if;

    update public.payments
    set amount = 0,
        payment_method = 'free'::public.payment_method,
        payment_proof_path = null,
        status = 'pending'::public.payment_status,
        paid_at = now(),
        verified_at = null,
        verified_by = null,
        notes = null,
        updated_at = now()
    where id = payment_record.id;
  else
    insert into public.payments (
      enrollment_id,
      amount,
      payment_method,
      payment_proof_path,
      status,
      paid_at
    ) values (
      enrollment_record.id,
      0,
      'free'::public.payment_method,
      null,
      'pending'::public.payment_status,
      now()
    );
  end if;

  return jsonb_build_object(
    'enrollment_id', enrollment_record.id,
    'status', 'active',
    'amount', 0
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.student_submit_payment(target_enrollment_id uuid, target_amount numeric, target_payment_proof_path text)
 RETURNS payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_profile_id uuid := (select auth.uid());
  enrollment_record public.enrollments%rowtype;
  payment_record public.payments%rowtype;
  expected_amount numeric;
begin
  if current_profile_id is null or not private.is_active_student() then
    raise exception 'Hanya peserta aktif yang dapat mengirim pembayaran.' using errcode = '42501';
  end if;

  if target_payment_proof_path is null or btrim(target_payment_proof_path) = '' then
    raise exception 'Bukti pembayaran wajib diisi.' using errcode = '22023';
  end if;

  select * into enrollment_record
  from public.enrollments
  where id = target_enrollment_id and profile_id = current_profile_id
  for update;

  if not found then
    raise exception 'Enrollment tidak ditemukan.' using errcode = 'P0002';
  end if;

  if not (
    (enrollment_record.payment_timing = 'upfront'::public.payment_timing and enrollment_record.status = 'pending_payment'::public.enrollment_status)
    or
    (enrollment_record.payment_timing = 'deferred'::public.payment_timing and enrollment_record.status = 'active'::public.enrollment_status)
  ) then
    raise exception 'Enrollment ini belum dapat menerima pembayaran.' using errcode = '22023';
  end if;

  expected_amount := greatest(enrollment_record.price_snapshot - enrollment_record.discount_amount, 0::numeric);

  if expected_amount <= 0 then
    raise exception 'Gunakan alur pembayaran Rp0 untuk enrollment ini.' using errcode = '22023';
  end if;

  if target_amount is distinct from expected_amount then
    raise exception 'Nominal pembayaran tidak sesuai total enrollment.' using errcode = '22023';
  end if;

  select * into payment_record
  from public.payments
  where enrollment_id = enrollment_record.id
  for update;

  if found then
    if payment_record.status <> 'rejected'::public.payment_status then
      raise exception 'Pembayaran sedang diproses atau sudah disetujui.' using errcode = '22023';
    end if;

    update public.payments
    set amount = expected_amount,
        payment_method = 'bank_transfer'::public.payment_method,
        payment_proof_path = btrim(target_payment_proof_path),
        status = 'pending'::public.payment_status,
        paid_at = now(),
        verified_at = null,
        verified_by = null,
        notes = null,
        updated_at = now()
    where id = payment_record.id
    returning * into payment_record;
  else
    insert into public.payments (
      enrollment_id, amount, payment_method, payment_proof_path, status, paid_at
    ) values (
      enrollment_record.id,
      expected_amount,
      'bank_transfer'::public.payment_method,
      btrim(target_payment_proof_path),
      'pending'::public.payment_status,
      now()
    )
    returning * into payment_record;
  end if;

  if enrollment_record.payment_timing = 'upfront'::public.payment_timing then
    update public.enrollments
    set status = 'pending_approval'::public.enrollment_status,
        activated_at = null,
        updated_at = now()
    where id = enrollment_record.id;
  end if;

  return payment_record;
end;
$function$
